-- Public interface copy is content: normalized per locale and edited in the console.
CREATE TABLE site_copy (id INTEGER PRIMARY KEY CHECK(id = 1));
CREATE TABLE site_copy_translations (copy_id INTEGER NOT NULL REFERENCES site_copy(id) ON DELETE CASCADE, locale TEXT NOT NULL CHECK(locale IN ('en','fr','ar')), skip_link TEXT NOT NULL, main_navigation TEXT NOT NULL, language_navigation TEXT NOT NULL, home TEXT NOT NULL, about TEXT NOT NULL, projects TEXT NOT NULL, contact TEXT NOT NULL, download_cv TEXT NOT NULL, view_projects TEXT NOT NULL, selected_work TEXT NOT NULL, all_projects TEXT NOT NULL, view_project TEXT NOT NULL, back_to_projects TEXT NOT NULL, education TEXT NOT NULL, experience TEXT NOT NULL, achievements TEXT NOT NULL, certificates TEXT NOT NULL, initiatives TEXT NOT NULL, skills TEXT NOT NULL, languages TEXT NOT NULL, present TEXT NOT NULL, role TEXT NOT NULL, outcomes TEXT NOT NULL, links TEXT NOT NULL, technologies TEXT NOT NULL, verify TEXT NOT NULL, related_projects TEXT NOT NULL, contact_heading TEXT NOT NULL, empty_projects TEXT NOT NULL, not_found_heading TEXT NOT NULL, not_found_body TEXT NOT NULL, return_home TEXT NOT NULL, PRIMARY KEY(copy_id, locale));
CREATE INDEX site_copy_locale ON site_copy_translations(locale);
